import { cn } from '@cascivo/core/pure'
import type { CSSProperties, HTMLAttributes, ReactNode } from 'react'
import styles from './aspect-ratio.module.css'

export interface AspectRatioProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * Width-to-height ratio applied via the CSS aspect-ratio property
   *
   * @defaultValue `16 / 9`
   * @see the component manifest
   */
  ratio?: number
  children?: ReactNode
}

export function AspectRatio({
  ratio = 16 / 9,
  className,
  style,
  children,
  ...props
}: AspectRatioProps) {
  return (
    <div
      className={cn(styles['root'], className)}
      style={{ '--cascivo-aspect-ratio': ratio, ...style } as CSSProperties}
      {...props}
    >
      <div className={styles['inner']}>{children}</div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    inline-size: 100%;
    aspect-ratio: var(--cascivo-aspect-ratio, 1);
  }

  .inner {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;

    & > * {
      inline-size: 100%;
      block-size: 100%;
      object-fit: cover;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'AspectRatio',
  description: 'Constrains content to a fixed width-to-height ratio',
  category: 'layout',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'ratio',
      type: 'number',
      required: false,
      default: '16 / 9',
      description: 'Width-to-height ratio applied via the CSS aspect-ratio property',
    },
    {
      name: 'children',
      type: 'ReactNode',
      required: false,
      description: 'Content to fill the ratio box (typically an image, video, or iframe)',
    },
  ],
  tokens: ['--cascivo-aspect-ratio'],
